#!/usr/bin/env bash
# setup.sh — 一次性配置 NJU HPC 自动化套件
# AI 代理运行本脚本；需要用户回答的问题都带默认值。
set -euo pipefail

KIT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
CONF="$KIT_DIR/hpc.conf"
SSH_CONFIG="$HOME/.ssh/config"
KEY_FILE="$HOME/.ssh/id_ed25519"

ask() {  # ask <prompt> <default>
    local prompt="$1" default="$2" reply
    read -r -p "$prompt [$default]: " reply || true
    printf '%s' "${reply:-$default}"
}

write_conf() {  # write_conf <login_ip>
    cat > "$CONF" <<EOF
# Generated by setup.sh on $(date -Is)
HPC_USER='$HPC_USER'
LOGIN_NODE='$LOGIN_NODE'
LOGIN_IP='${1:-}'
USERLAND_PORT='$USERLAND_PORT'
ENTRY_HOST='$ENTRY_HOST'
SSH_ALIAS='nju-hpc'
SSH_ALIAS_ENTRY='nju-hpc-entry'
KEY_FILE='$KEY_FILE'
KIT_DIR='$KIT_DIR'
EOF
    chmod 600 "$CONF"
}

echo "== NJU HPC kit setup =="
HPC_USER=""
while [ -z "$HPC_USER" ]; do
    HPC_USER="$(ask "集群用户名（必填，如 abc123）" "")"
done
LOGIN_NODE="$(ask "登录节点" "login2")"
ENTRY_HOST="$(ask "双认证网关" "entry.nju.edu.cn")"
USERLAND_PORT="$(ask "用户态 sshd 端口" "29422")"

mkdir -p "$HOME/.ssh" && chmod 700 "$HOME/.ssh"
if [ ! -f "$KEY_FILE" ]; then
    ssh-keygen -t ed25519 -N '' -f "$KEY_FILE" -q
    echo "-> 生成本机密钥 $KEY_FILE"
fi

write_conf ""
echo "-> wrote $CONF"

touch "$SSH_CONFIG"; chmod 600 "$SSH_CONFIG"
if ! grep -q "Host $SSH_ALIAS_ENTRY" "$SSH_CONFIG" 2>/dev/null; then
    cat >> "$SSH_CONFIG" <<EOF

Host $SSH_ALIAS_ENTRY
  HostName $ENTRY_HOST
  User $HPC_USER

Host $SSH_ALIAS
  HostName $LOGIN_NODE
  User $HPC_USER
EOF
    echo "-> ssh config 已追加别名（$SSH_ALIAS_ENTRY, $SSH_ALIAS）"
else
    echo "-> ssh config 别名已存在，跳过"
fi

echo
echo "== 网络环境确认 =="
cat <<'EOF'
是否已处于校内网 / 已连接可访问校园资源的 VPN？
  y) 是 —— 接下来请你输入一次集群密码，之后自动完成：
        公钥安装 + 用户态 sshd 部署 + 免密直连（campus 模式，断线自动重连）。
  n) 否 —— 跳过；之后首次 start-session.sh 时会引导做一次
        密码 + 两步认证，并在认证后自动完成上述部署。
EOF
read -r -p "校内网环境? (y/n) [n]: " oncampus || oncampus="n"

if [ "$oncampus" = "y" ]; then
    echo "首次登录需要密码（仅一次）..."
    target="$HPC_USER@$LOGIN_NODE"
    if ssh -o PreferredAuthentications=password,keyboard-interactive "$target" true 2>/dev/null; then
        pub="$(base64 -w0 "$KEY_FILE.pub")"
        ssh "$target" "PUB_B64='$pub' PORT='$USERLAND_PORT' bash -s" < "$KIT_DIR/ensure-userland.sh"
        ip="$(ssh "$target" 'hostname -I' | tr ' ' '\n' | grep -E '^210\.28\.' | head -1)"
        if [ -n "$ip" ]; then
            write_conf "$ip"
            sed -i "/Host $SSH_ALIAS\$/,/User /s/HostName .*/HostName $ip/" "$SSH_CONFIG" 2>/dev/null || true
            echo "-> campus 模式就绪：$HPC_USER@$ip:$USERLAND_PORT（免密）"
        fi
    else
        echo "!! 直连登录失败；可稍后重跑 setup.sh 或改用 start-session.sh" >&2
    fi
else
    echo "-> 跳过免密配置（校外网模式）。首次使用请先运行 start-session.sh。"
fi

echo
echo "== 冒烟测试 =="
bash "$KIT_DIR/detect-net.sh" || true
echo
echo "setup 完成。日常使用：bash $KIT_DIR/run-session.sh 'hostname'"
